// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount <= address(this).balance + 1e30);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == amount);
    }
}
